#!/bin/sh
# Generated by scripts/sync_versions.py. Runtime code comes only from the Python artifact.
set -eu
PACKAGE_NAME='mlca'
VERSION='0.2.0b1'
ASSUME_YES=0
MODIFY_PATH=1
while [ "$#" -gt 0 ]; do
  case "$1" in
    --version) [ "$#" -ge 2 ] || { echo '--version needs a value' >&2; exit 2; }; VERSION=$2; shift 2 ;;
    --yes) ASSUME_YES=1; shift ;;
    --no-modify-path) MODIFY_PATH=0; shift ;;
    --help) echo 'Usage: install.sh [--version X] [--yes] [--no-modify-path]'; exit 0 ;;
    *) echo "Unknown argument: $1" >&2; exit 2 ;;
  esac
done
case "$VERSION" in *[!A-Za-z0-9._+-]*) echo 'Invalid version' >&2; exit 2 ;; esac
OS=$(uname -s)
ARCH=$(uname -m)
case "$OS" in Linux|Darwin) ;; *) echo "Unsupported OS: $OS. Use install.ps1 on native Windows." >&2; exit 1 ;; esac
echo "Installing MLCA for $OS/$ARCH"
if ! command -v uv >/dev/null 2>&1; then
  echo 'uv is required. This will run the official Astral installer (https://astral.sh/uv/install.sh).'
  if [ "$ASSUME_YES" -ne 1 ]; then
    if [ ! -r /dev/tty ]; then echo 'Run with --yes to consent without a terminal.' >&2; exit 1; fi
    printf 'Install uv? [y/N] ' >/dev/tty
    read -r consent </dev/tty || exit 1
    case "$consent" in y|Y|yes|YES) ;; *) exit 1 ;; esac
  fi
  installer=$(mktemp)
  trap 'rm -f "$installer"' EXIT HUP INT TERM
  curl -LsSf https://astral.sh/uv/install.sh -o "$installer"
  if [ "$MODIFY_PATH" -eq 0 ]; then UV_NO_MODIFY_PATH=1 sh "$installer"; else sh "$installer"; fi
  PATH="${UV_INSTALL_DIR:-$HOME/.local/bin}:$PATH"
  export PATH
fi
if [ -n "$VERSION" ]; then
  uv tool install --reinstall "$PACKAGE_NAME==$VERSION"
elif uv tool list | awk '{print $1}' | grep -Fx "$PACKAGE_NAME" >/dev/null; then
  uv tool upgrade "$PACKAGE_NAME"
else
  uv tool install "$PACKAGE_NAME"
fi
if [ "$MODIFY_PATH" -eq 1 ]; then uv tool update-shell; fi
if [ "$OS" = Linux ] && ! command -v bwrap >/dev/null 2>&1; then
  echo 'Level A requires bubblewrap. Install it yourself with:'
  if command -v apt-get >/dev/null 2>&1; then echo 'sudo apt install bubblewrap'
  elif command -v dnf >/dev/null 2>&1; then echo 'sudo dnf install bubblewrap'
  elif command -v pacman >/dev/null 2>&1; then echo 'sudo pacman -S bubblewrap'
  elif command -v zypper >/dev/null 2>&1; then echo 'sudo zypper install bubblewrap'
  else echo 'Install bubblewrap with your distribution package manager.'; fi
fi
if [ "$OS" = Darwin ]; then
  echo 'macOS uses weaker level B. Opt in for trusted code with sandbox.allow_level_b: true in config.yaml.'
fi
tool_bin=$(uv tool dir --bin)
"$tool_bin/mlca" doctor
